params.spec:
{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "description": "The highest-severity scoring actions in range (the top 12 by severity, rarest first within a weight), one row per action and weight, placed by how often each happened. Each row ends with its severity weight (· 45), which the colour repeats: one colour per weight, from blue for 10 to deep red for 50, listed in the key below the chart. Rarest is on the left, so the top-left corner is rare and high-severity: where to look first. A failed action gets its own row, marked (failed) unless its name already says so; a failed Kibana change scores 40 whatever it changed. Hover a point for how many identities did it and when.",
  "title": {
    "text": {
      "expr": "length(data('actions')) > 12 ? 'Top 12 of ' + length(data('actions')) + ' scoring actions, by severity, rarest first within a weight' : length(data('actions')) ? (length(data('actions')) == 1 ? '1 scoring action' : length(data('actions')) + ' scoring actions') + ', by severity, rarest first within a weight' : 'No scoring actions for this selection in this time range'"
    }
  },
  "autosize": {
    "type": "fit",
    "contains": "padding"
  },
  "config": {
    "axis": {
      "labelFontSize": 11,
      "titleFontSize": 11
    },
    "view": {
      "stroke": null
    },
    "title": {
      "fontSize": 11,
      "fontWeight": "normal",
      "anchor": "start",
      "offset": 8
    },
    "legend": {
      "labelFontSize": 11,
      "titleFontSize": 11
    }
  },
  "data": {
    "name": "actions",
    "url": {
      "%type%": "esql",
      "query": "FROM logs-elastic_cloud.serverless_audit.otel-* | WHERE @timestamp <= ?_tend AND @timestamp > ?_tstart | WHERE attributes.elasticsearch.audit.security_config_change IS NOT NULL OR attributes.event.outcome == \"failure\" OR attributes.event.action IN (\"invalidate_apikeys\",\"anonymous_access_denied\") OR (resource.attributes.service.name == \"serverless-kibana\" AND ((attributes.event.type IN (\"change\",\"creation\",\"deletion\") AND (attributes.event.action IS NULL OR NOT (attributes.event.action IN (\"saved_object_open_point_in_time\",\"saved_object_close_point_in_time\")))) OR attributes.event.action IN (\"rule_run_soon\",\"secret_create\"))) | STATS n = COUNT(*), ts_min = MIN(@timestamp), ts_max = MAX(@timestamp) BY attributes.user.email, attributes.api_key.name, attributes.user.name, attributes.event.action, scc = attributes.elasticsearch.audit.security_config_change IS NOT NULL, attributes.event.outcome, resource.attributes.service.name, et = MV_CONCAT(attributes.event.type, \",\"), housekeeping = (attributes.event.action IS NOT NULL AND attributes.event.action == \"invalidate_apikeys\" AND attributes.user.name IS NOT NULL AND attributes.user.name IN (\"elastic.maintenance\",\"autoscaling\",\"elasticsearch-controller\",\"elastic/fleet-server\",\"elastic/kibana\") AND attributes.api_key.name IS NULL) | EVAL attributes.event.type = SPLIT(et, \",\"), attributes.elasticsearch.audit.security_config_change = CASE(scc, \"present\") | EVAL risk = CASE(housekeeping, 0, attributes.event.action == \"invalidate_apikeys\", 45, attributes.event.action == \"anonymous_access_denied\", 35, attributes.elasticsearch.audit.security_config_change IS NOT NULL, 50, attributes.event.outcome == \"failure\", 40, (resource.attributes.service.name == \"serverless-kibana\" AND ((attributes.event.type IN (\"change\",\"creation\",\"deletion\") AND (attributes.event.action IS NULL OR NOT (attributes.event.action IN (\"saved_object_open_point_in_time\",\"saved_object_close_point_in_time\")))) OR attributes.event.action IN (\"rule_run_soon\",\"secret_create\"))) AND attributes.event.action IN (\"workflow_run\",\"workflow_test\",\"workflow_execution_cancel\"), 10, (resource.attributes.service.name == \"serverless-kibana\" AND ((attributes.event.type IN (\"change\",\"creation\",\"deletion\") AND (attributes.event.action IS NULL OR NOT (attributes.event.action IN (\"saved_object_open_point_in_time\",\"saved_object_close_point_in_time\")))) OR attributes.event.action IN (\"rule_run_soon\",\"secret_create\"))) AND (attributes.event.type == \"deletion\" OR attributes.event.action == \"rule_disable\"), 30, (resource.attributes.service.name == \"serverless-kibana\" AND ((attributes.event.type IN (\"change\",\"creation\",\"deletion\") AND (attributes.event.action IS NULL OR NOT (attributes.event.action IN (\"saved_object_open_point_in_time\",\"saved_object_close_point_in_time\")))) OR attributes.event.action IN (\"rule_run_soon\",\"secret_create\"))), 25, 0) | WHERE risk > 0 | EVAL actor = COALESCE(attributes.user.email, attributes.api_key.name, attributes.user.name, \"<anonymous>\") | STATS events = SUM(n), identities = COUNT_DISTINCT(actor), first_ts = MIN(ts_min), last_ts = MAX(ts_max) BY action = attributes.event.action, risk, failed = attributes.event.outcome == \"failure\" | EVAL label = CASE(failed AND NOT (action LIKE \"*fail*\" OR action LIKE \"*denied*\"), CONCAT(action, \" (failed)\"), action) | EVAL label = CONCAT(label, \" · \", TO_STRING(risk)) | SORT risk DESC, events ASC, label ASC | LIMIT 200",
      "%timefield%": "@timestamp",
      "%context%": true
    }
  },
  "transform": [
    {
      "window": [
        {
          "op": "row_number",
          "as": "rank"
        }
      ],
      "sort": [
        {
          "field": "risk",
          "order": "descending"
        },
        {
          "field": "events",
          "order": "ascending"
        },
        {
          "field": "label",
          "order": "ascending"
        }
      ]
    },
    {
      "filter": "datum.rank <= 12"
    },
    {
      "calculate": "'' + datum.risk",
      "as": "weight"
    }
  ],
  "mark": {
    "type": "point",
    "filled": true,
    "size": 130,
    "opacity": 1,
    "stroke": "#69707D",
    "strokeWidth": 1
  },
  "encoding": {
    "x": {
      "field": "events",
      "type": "quantitative",
      "scale": {
        "type": "log",
        "domainMin": 1,
        "nice": false,
        "padding": 14
      },
      "axis": {
        "title": "Occurrences in range (log scale) · rarer to the left",
        "format": "~s",
        "values": [
          1,
          3,
          10,
          30,
          100,
          300,
          1000,
          3000,
          10000,
          30000,
          100000,
          300000,
          1000000,
          3000000,
          10000000
        ]
      }
    },
    "y": {
      "field": "label",
      "type": "nominal",
      "sort": {
        "field": "rank",
        "op": "min",
        "order": "ascending"
      },
      "axis": {
        "title": null,
        "labelLimit": 240,
        "grid": true
      }
    },
    "color": {
      "field": "weight",
      "type": "nominal",
      "scale": {
        "domain": [
          "50",
          "45",
          "40",
          "35",
          "30",
          "25",
          "10"
        ],
        "range": [
          "#BD271E",
          "#E7664C",
          "#DA8B45",
          "#D6BF57",
          "#A0A65A",
          "#54B399",
          "#6092C0"
        ]
      },
      "legend": {
        "title": "Severity weight",
        "orient": "bottom",
        "direction": "horizontal",
        "offset": 6,
        "symbolType": "circle",
        "symbolSize": 90,
        "columns": 7,
        "columnPadding": 10,
        "labelFontSize": 11,
        "titleFontSize": 11,
        "titleOrient": "left",
        "values": {
          "expr": "length(data('actions')) ? split(trim((indexof('|' + join(pluck(slice(data('actions'), 0, 12), 'risk'), '|') + '|', '|50|') >= 0 ? '50 ' : '') + (indexof('|' + join(pluck(slice(data('actions'), 0, 12), 'risk'), '|') + '|', '|45|') >= 0 ? '45 ' : '') + (indexof('|' + join(pluck(slice(data('actions'), 0, 12), 'risk'), '|') + '|', '|40|') >= 0 ? '40 ' : '') + (indexof('|' + join(pluck(slice(data('actions'), 0, 12), 'risk'), '|') + '|', '|35|') >= 0 ? '35 ' : '') + (indexof('|' + join(pluck(slice(data('actions'), 0, 12), 'risk'), '|') + '|', '|30|') >= 0 ? '30 ' : '') + (indexof('|' + join(pluck(slice(data('actions'), 0, 12), 'risk'), '|') + '|', '|25|') >= 0 ? '25 ' : '') + (indexof('|' + join(pluck(slice(data('actions'), 0, 12), 'risk'), '|') + '|', '|10|') >= 0 ? '10 ' : '')), ' ') : []"
        }
      }
    },
    "tooltip": [
      {
        "field": "action",
        "title": "Action"
      },
      {
        "field": "risk",
        "title": "Severity weight"
      },
      {
        "field": "events",
        "title": "Occurrences",
        "format": ","
      },
      {
        "field": "identities",
        "title": "Identities",
        "format": ","
      },
      {
        "field": "first_ts",
        "title": "First in range",
        "type": "temporal",
        "format": "%b %d, %H:%M:%S"
      },
      {
        "field": "last_ts",
        "title": "Last in range",
        "type": "temporal",
        "format": "%b %d, %H:%M:%S"
      }
    ]
  }
}
